    def get_listing(
        self,
        posting_id: str,
        *,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> ImovelwebListingDetail:
        """Returns one listing with its description, prices, fees, location, photos, floor plans, amenities, publisher, and development details when applicable. Costs 2 credits.

        Args:
            posting_id: imovelweb listing id: the number at the end of a listing URL
                (`...-3047460005.html`).
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.imovelweb.ImovelwebListingDetail`.
        """
        return self._send(_get_listing(posting_id), timeout=timeout)

    def list_listing_publishers(
        self,
        posting_id: str,
        *,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> ImovelwebListingPublishers:
        """Returns every publisher advertising the same property, with each publisher's listing ID, URL, name, logo, and ad tier. Listings without duplicates return an empty list. Costs 1 credit.

        Args:
            posting_id: imovelweb listing id: the number at the end of a listing URL
                (`...-3047460005.html`).
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.imovelweb.ImovelwebListingPublishers`.
        """
        return self._send(_list_listing_publishers(posting_id), timeout=timeout)

    def list_similar_listings(
        self,
        posting_id: str,
        *,
        limit: int = 20,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> ImovelwebSimilarListings:
        """Returns listings with a similar area, property type, and price range. Each item includes its operation, price, rooms, area, address, and photos. Costs 1 credit.

        Args:
            posting_id: imovelweb listing id: the number at the end of a listing URL
                (`...-3047460005.html`).
            limit: Listings to return.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.imovelweb.ImovelwebSimilarListings`.
        """
        return self._send(_list_similar_listings(posting_id, limit=limit), timeout=timeout)

    def list_locations(
        self,
        *,
        query: str,
        limit: int = 10,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> ImovelwebLocations:
        """Location autocomplete: states, cities and neighbourhoods matching the text, at most 10, each with its `level` and the `id` that `location_id` on `/listings` takes. A query with no match answers an empty list. Costs 1 credit.

        Args:
            query: Place name, such as `pinheiros` or `rio de janeiro`.
            limit: Suggestions to return.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.imovelweb.ImovelwebLocations`.
        """
        return self._send(_list_locations(query=query, limit=limit), timeout=timeout)

    def get_publisher(
        self,
        publisher_id: str,
        *,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> ImovelwebPublisher:
        """Returns a broker or developer profile with contact details, address, logo, listing counts, and buyer ratings. Use `/listings?publisher_id=` for its listings. Costs 2 credits.

        Args:
            publisher_id: imovelweb publisher (agency, developer or owner) id:
                `publisher.id` on a listing.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.imovelweb.ImovelwebPublisher`.
        """
        return self._send(_get_publisher(publisher_id), timeout=timeout)
